/// <summary>
/// Response data contract class for <c>METUpdateSalesInvoiceIntegrationStatusService</c> class.
/// </summary>
[DataContractAttribute]
class METSalesOrderGuideResponseContract
{
    private boolean     isOnOrderGuide;
    private ItemId      itemId;
}

Method.Source:
    /// <summary>
    /// Method to specify if an item is orderable
    /// </summary>
    /// <param name = "_isOnOrderGuide">boolean value indicating if an item is orderable</param>
    /// <returns>True if isOnOrderGuide/ else false</returns>
    [
        DataMemberAttribute('IsOnOrderGuide')
    ]
    public Boolean parmIsOnOrderGuide(Boolean _isOnOrderGuide = isOnOrderGuide)
    {
        if (!prmIsDefault(_isOnOrderGuide))
        {
            isOnOrderGuide = _isOnOrderGuide;
        }

        return isOnOrderGuide;
    }

/// <summary>
/// Method to specify the item number
/// </summary>
/// <param name = "_itemId">Item number</param>
/// <returns>return the item number</returns>
[
    DataMemberAttribute('ItemId')
]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    if (!prmIsDefault(_itemId))
    {
        itemId = _itemId;
    }
    return itemId;
}
